import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { register } from "node:module";

/**
 * Turn the authored curriculum into a migration.
 *
 * `src/lib/curriculum` is the source; the migration this writes is the
 * artifact. Both are committed, because the database is what the application
 * reads and a generated file nobody can see is a file nobody reviews.
 *
 * The whole programme is emitted as a single dollar-quoted JSON document and
 * unpacked by PL/pgSQL. That is deliberate: one escaping surface instead of
 * thousands of string literals, and the delimiter is asserted absent from the
 * content before anything is written.
 *
 *   node --experimental-strip-types scripts/build-curriculum.mjs
 */

register(pathToFileURL(path.join(import.meta.dirname, "alias-hooks.mjs")));

const { CURRICULUM } = await import("../src/lib/curriculum/index.ts");
const { blockSchema } = await import("../src/lib/learning/blocks.ts");

/* Re-validate here as well as in the tests: this is the last gate before the
   content becomes SQL, and a build step that trusts its input is not a gate. */
const problems = [];
for (const phase of CURRICULUM) {
  for (const entry of phase.modules) {
    for (const lesson of entry.lessons) {
      for (const block of lesson.blocks) {
        const parsed = blockSchema.safeParse(block);
        if (!parsed.success) problems.push(`${lesson.slug}/${block.id}`);
      }
    }
    for (const block of entry.mission?.blocks ?? []) {
      const parsed = blockSchema.safeParse(block);
      if (!parsed.success) problems.push(`${entry.mission.slug}/${block.id}`);
    }
  }
}
if (problems.length) {
  console.error("invalid blocks:", problems.join(", "));
  process.exit(1);
}

/* The document the migration unpacks. Flattened here rather than in SQL,
   because positions and defaults are easier to get right in JavaScript. */
const doc = {
  modules: [],
  lessons: [],
  missions: [],
};

for (const phase of CURRICULUM) {
  phase.modules.forEach((entry, moduleIndex) => {
    doc.modules.push({
      phase_key: phase.key,
      slug: entry.slug,
      title: entry.title,
      summary: entry.summary,
      position: moduleIndex + 1,
    });

    entry.lessons.forEach((lesson, lessonIndex) => {
      doc.lessons.push({
        module_slug: entry.slug,
        slug: lesson.slug,
        title: lesson.title,
        summary: lesson.summary,
        type: lesson.type,
        difficulty: lesson.difficulty,
        estimated_minutes: lesson.minutes,
        objectives: lesson.objectives,
        blocks: lesson.blocks,
        completion_rule: lesson.completion,
        position: lessonIndex + 1,
        skills: lesson.skills ?? [],
        toolbox: lesson.toolbox ?? [],
        requires: lesson.requires ?? [],
      });
    });

    const mission = entry.mission;
    if (!mission) return;
    doc.missions.push({
      phase_key: phase.key,
      module_slug: entry.slug,
      slug: mission.slug,
      title: mission.title,
      summary: mission.summary,
      type: mission.type,
      difficulty: mission.difficulty,
      estimated_minutes: mission.minutes,
      objective: mission.objective,
      why_it_matters: mission.whyItMatters,
      objectives: mission.objectives,
      blocks: mission.blocks,
      deliverable_title: mission.deliverableTitle,
      deliverable_description: mission.deliverableDescription,
      required_evidence: mission.requiredEvidence,
      requires_reflection: mission.requiresReflection ?? false,
      requires_lesson: mission.requiresLesson ?? null,
      position: moduleIndex + 1,
      skills: mission.skills ?? [],
      toolbox: mission.toolbox ?? [],
    });
  });
}

const json = JSON.stringify(doc, null, 1);
const DELIM = "$lockcurriculum$";
if (json.includes(DELIM) || json.includes("$lockbody$")) {
  console.error("content collides with a SQL dollar-quote delimiter");
  process.exit(1);
}

const counts = {
  phases: CURRICULUM.length,
  modules: doc.modules.length,
  lessons: doc.lessons.length,
  missions: doc.missions.length,
};

const sql = `-- Generated by scripts/build-curriculum.mjs. Do not edit by hand.
--
-- The real LOCK curriculum: ${counts.phases} phases, ${counts.modules} modules,
-- ${counts.lessons} lessons and ${counts.missions} missions, replacing the demonstration
-- content the learning engine was built against.
--
-- The source is \`src/lib/curriculum\`, where every block is typed against the
-- same union the renderer reads and every editorial rule is a test. Regenerate
-- with:
--
--     node --experimental-strip-types scripts/build-curriculum.mjs
--
-- ── What this migration removes ─────────────────────────────────────────────
--
-- Every module, lesson and mission that existed before, along with the one
-- toolbox item and the one lesson resource that were placeholders — including a
-- resource whose URL was a well-known joke video. Deleting a module cascades to
-- its lessons and to any learner progress against them, which is correct: the
-- demonstration content is being retired, not edited, and progress against a
-- lesson that no longer exists is not progress.
--
-- Phases, skills, milestones, XP rules and the real toolbox items are left
-- alone. They were already the product's own vocabulary rather than samples.

begin;

-- ── Out with the demonstration content ──────────────────────────────────────

delete from public.missions;
delete from public.modules;

-- Two rows that were only ever scaffolding for the renderer.
delete from public.toolbox_items where is_demo;
delete from public.lesson_resources where url like '%dQw4w9WgXcQ%';

-- ── In with the programme ───────────────────────────────────────────────────

do $lockbody$
declare
  doc jsonb := ${DELIM}${json}${DELIM}::jsonb;
  rec jsonb;
  inner_rec jsonb;
  v_module_id uuid;
  v_lesson_id uuid;
  v_mission_id uuid;
  v_requires_id uuid;
  v_item_id uuid;
  v_position smallint;
begin
  -- Modules first: lessons and missions both hang off them.
  for rec in select * from jsonb_array_elements(doc -> 'modules')
  loop
    insert into public.modules (phase_key, slug, title, summary, position, status)
    values (
      rec ->> 'phase_key',
      rec ->> 'slug',
      rec ->> 'title',
      rec ->> 'summary',
      (rec ->> 'position')::smallint,
      'published'
    );
  end loop;

  -- Lessons, with their skills and toolbox links. Prerequisites come after,
  -- because a lesson can require one that has not been inserted yet.
  for rec in select * from jsonb_array_elements(doc -> 'lessons')
  loop
    select id into v_module_id from public.modules where slug = rec ->> 'module_slug';
    if v_module_id is null then
      raise exception 'no module % for lesson %', rec ->> 'module_slug', rec ->> 'slug';
    end if;

    insert into public.lessons (
      module_id, slug, title, summary, type, difficulty, estimated_minutes,
      objectives, blocks, completion_rule, position, is_demo, status
    )
    values (
      v_module_id,
      rec ->> 'slug',
      rec ->> 'title',
      rec ->> 'summary',
      (rec ->> 'type')::public.lesson_type,
      (rec ->> 'difficulty')::public.lesson_difficulty,
      (rec ->> 'estimated_minutes')::smallint,
      array(select jsonb_array_elements_text(rec -> 'objectives')),
      rec -> 'blocks',
      (rec ->> 'completion_rule')::public.completion_rule,
      (rec ->> 'position')::smallint,
      false,
      'published'
    )
    returning id into v_lesson_id;

    for inner_rec in select * from jsonb_array_elements(rec -> 'skills')
    loop
      insert into public.lesson_skills (lesson_id, skill_key)
      select v_lesson_id, s.key from public.skills s where s.key = inner_rec #>> '{}'
      on conflict do nothing;
    end loop;

    v_position := 0;
    for inner_rec in select * from jsonb_array_elements(rec -> 'toolbox')
    loop
      select id into v_item_id from public.toolbox_items where slug = inner_rec #>> '{}';
      if v_item_id is not null then
        insert into public.lesson_toolbox_items (lesson_id, item_id, position)
        values (v_lesson_id, v_item_id, v_position)
        on conflict do nothing;
        v_position := v_position + 1;
      end if;
    end loop;
  end loop;

  -- Prerequisites, now that every lesson exists.
  for rec in select * from jsonb_array_elements(doc -> 'lessons')
  loop
    select id into v_lesson_id from public.lessons where slug = rec ->> 'slug';
    for inner_rec in select * from jsonb_array_elements(rec -> 'requires')
    loop
      select id into v_requires_id from public.lessons where slug = inner_rec #>> '{}';
      if v_requires_id is null then
        raise exception 'lesson % requires missing %', rec ->> 'slug', inner_rec #>> '{}';
      end if;
      insert into public.lesson_prerequisites (lesson_id, requires_lesson_id)
      values (v_lesson_id, v_requires_id)
      on conflict do nothing;
    end loop;
  end loop;

  -- Missions.
  for rec in select * from jsonb_array_elements(doc -> 'missions')
  loop
    select id into v_module_id from public.modules where slug = rec ->> 'module_slug';

    v_requires_id := null;
    if rec ->> 'requires_lesson' is not null then
      select id into v_requires_id from public.lessons where slug = rec ->> 'requires_lesson';
      if v_requires_id is null then
        raise exception 'mission % requires missing lesson %',
          rec ->> 'slug', rec ->> 'requires_lesson';
      end if;
    end if;

    insert into public.missions (
      phase_key, module_id, requires_lesson_id, slug, title, summary, type,
      difficulty, estimated_minutes, objective, why_it_matters, objectives,
      blocks, deliverable_title, deliverable_description, required_evidence,
      requires_reflection, position, is_demo, status
    )
    values (
      rec ->> 'phase_key',
      v_module_id,
      v_requires_id,
      rec ->> 'slug',
      rec ->> 'title',
      rec ->> 'summary',
      (rec ->> 'type')::public.mission_type,
      (rec ->> 'difficulty')::public.lesson_difficulty,
      (rec ->> 'estimated_minutes')::smallint,
      rec ->> 'objective',
      rec ->> 'why_it_matters',
      array(select jsonb_array_elements_text(rec -> 'objectives')),
      rec -> 'blocks',
      rec ->> 'deliverable_title',
      rec ->> 'deliverable_description',
      array(select jsonb_array_elements_text(rec -> 'required_evidence'))::public.evidence_kind[],
      (rec ->> 'requires_reflection')::boolean,
      (rec ->> 'position')::smallint,
      false,
      'published'
    )
    returning id into v_mission_id;

    for inner_rec in select * from jsonb_array_elements(rec -> 'skills')
    loop
      insert into public.mission_skills (mission_id, skill_key, is_primary)
      select v_mission_id, s.key, coalesce((inner_rec ->> 'primary')::boolean, false)
      from public.skills s
      where s.key = inner_rec ->> 'key'
      on conflict do nothing;
    end loop;

    v_position := 0;
    for inner_rec in select * from jsonb_array_elements(rec -> 'toolbox')
    loop
      select id into v_item_id from public.toolbox_items where slug = inner_rec #>> '{}';
      if v_item_id is not null then
        insert into public.mission_toolbox_items (mission_id, item_id, position)
        values (v_mission_id, v_item_id, v_position)
        on conflict do nothing;
        v_position := v_position + 1;
      end if;
    end loop;
  end loop;
end
$lockbody$;

-- ── What must be true afterwards ────────────────────────────────────────────
--
-- Asserted here rather than trusted, because a seed that silently inserts
-- nothing looks identical to one that worked.

do $lockbody$
declare
  v_modules integer;
  v_lessons integer;
  v_missions integer;
  v_unpublished integer;
begin
  select count(*) into v_modules from public.modules;
  select count(*) into v_lessons from public.lessons;
  select count(*) into v_missions from public.missions;

  if v_modules <> ${counts.modules} or v_lessons <> ${counts.lessons} or v_missions <> ${counts.missions} then
    raise exception 'curriculum did not load: % modules, % lessons, % missions',
      v_modules, v_lessons, v_missions;
  end if;

  select count(*) into v_unpublished
  from public.lessons where not published;
  if v_unpublished > 0 then
    raise exception '% lessons are not published', v_unpublished;
  end if;

  -- Every phase must have something in it. A phase a learner cannot enter is
  -- the placeholder state this migration exists to remove.
  if exists (
    select 1 from public.phases p
    where not exists (select 1 from public.modules m where m.phase_key = p.key)
  ) then
    raise exception 'a phase has no modules';
  end if;

  -- And nothing may claim to be demonstration content any more.
  if exists (select 1 from public.lessons where is_demo)
     or exists (select 1 from public.missions where is_demo)
     or exists (select 1 from public.toolbox_items where is_demo) then
    raise exception 'demonstration content survived the migration';
  end if;
end
$lockbody$;

commit;
`;

const out = path.join(import.meta.dirname, "..", "supabase", "migrations", "20260913000000_curriculum.sql");
await writeFile(out, sql, "utf8");

const bytes = (await readFile(out)).length;
console.log(
  `wrote ${path.relative(process.cwd(), out)} — ` +
    `${counts.phases} phases, ${counts.modules} modules, ${counts.lessons} lessons, ` +
    `${counts.missions} missions, ${(bytes / 1024).toFixed(0)} kB`,
);
